"""Controlled expansion batch 012: whole-carrot UHPLC/DAD/MS and HPLC/DAD tables."""
from pathlib import Path
import hashlib,json
import pandas as pd
R=Path(__file__).resolve().parent;PARENT=R.parent/'batch_011'/'updated_master_dataset.csv'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(n,t):(R/n).write_text(t.strip()+'\n',encoding='utf-8')
base=pd.read_csv(PARENT)
def template(x):
 f=base.loc[base.compound.astype(str).str.casefold().eq(x.casefold())];assert len(f),x;return f.iloc[0]
methods=[('Boiling','boiling',pd.NA,38,'boiling tap water, raw carrot:water mass ratio 1:4'),('Steaming in steel pot','steaming',pd.NA,50,'perforated insert in steel pot'),('Steaming in combi oven','steaming',pd.NA,55,'Retigo B623i combi oven, steam'),('Baking','baking',180,46,'wrapped in aluminum foil; Retigo B623i combi oven'),('Sous-vide','sous vide',85,105,'vacuum-sealed PA/PE bags, water bath circulator')]
# Tables 3–4, means ± SD µg/g dry weight; only exact existing compound identities.
data={'Caffeic acid':(253.30,.03,[(460.60,5.73),(354.21,.83),(424.21,1.06),(404.16,3.79),(327.62,1.39)]),'Chlorogenic Acid':(1026.10,16.28,[(2674.49,26.55),(2223.27,8.60),(1473.49,19.01),(2002.19,.63),(992.40,1.64)]),'Ferulic Acid':(162.56,.11,[(163.93,.11),(177.15,1.28),(154.75,1.76),(172.75,1.85),(160.11,1.49)]),'p-Coumaric acid':(71.80,.01,[(82.08,.21),(80.74,.93),(76.13,1.07),(82.95,.11),(74.54,.05)]),'Lutein':(29.87,2.50,[(51.03,.13),(53.15,1.09),(43.59,1.74),(49.84,.43),(40.58,.19)]),'Beta-Carotene':(152.29,4.10,[(270.08,6.72),(218.01,3.99),(190.05,7.13),(272.22,5.33),(193.09,5.90)])}
rows=[]
for compound,(raw,raw_sd,cells) in data.items():
 for (method,norm,temp,mins,medium),(cooked,cooked_sd) in zip(methods,cells):
  src=template(compound);safe=compound.upper().replace(' ','_').replace('-','_');protocol=method.upper().replace(' ','_').replace('-','_');row={c:src[c] for c in base.columns};row.update({'observation_id':f'LIT-NARWOJSZ2025-CARROT-{safe}-{protocol}', 'original_record_id':'','doi':'10.3390/app15010254','paper_id':'NEW_LITERATURE_NARWOJSZ_2025','source_locator':'Tables 3–4; Methods §§2.2–2.5.2','compound':compound,'food_matrix':'Whole unpeeled carrot roots (Daucus carota L. var. Berlikumer 2–Perfekcja)','cooking_method':method,'cooking_method_normalized':norm,'cooking_medium':medium,'raw_concentration':raw,'raw_sd':raw_sd,'cooked_concentration':cooked,'cooked_sd':cooked_sd,'concentration_unit':'µg/g dry weight','measurement_basis':'dry weight (DW)','target_name':'apparent_concentration_ratio_percent','target_equation':'100 * C_cooked / C_raw','target_value_percent':100*cooked/raw,'target_semantics':'apparent concentration ratio; not total-mass retention','evidence_status':'VERIFIED_PRIMARY_TABLE','cooked_yield_status':'NOT_REPORTED','total_mass_retention_status':'NOT_ESTABLISHED','source_detail':'Narwojsz et al. (2025), Tables 3–4: individual standard-quantified phenolics by UHPLC-DAD-MS and carotenoids by RP-HPLC-DAD. Heat treatments performed in triplicate; table mean ± SD retained.','Temperature_C':temp,'Cooking_Time_min':mins,'reported_replicate_design':'Heat treatments conducted in triplicate; Table data mean ± SD (n=3). No technical rows expanded.','analytical_definition':'Individual UHPLC-DAD-MS phenolic or RP-HPLC-DAD carotenoid analyte; dry-weight result'}) ;rows.append(row)
new=pd.DataFrame(rows,columns=base.columns);master=pd.concat([base,new],ignore_index=True)
assert len(new)==30 and len(master)==749 and master.doi.nunique()==25 and new.canonical_molecular_id.notna().all() and not master.observation_id.duplicated().any() and (new.target_value_percent.round(8)==(100*new.cooked_concentration/new.raw_concentration).round(8)).all()
master.to_csv(R/'updated_master_dataset.csv',index=False);new.to_csv(R/'verified_observations.csv',index=False);new.to_csv(R/'extracted_observations.csv',index=False)
pd.DataFrame([{'doi':'10.3390/app15010254','title':'Effect of Heat Treatment Methods on Color, Bioactive Compound Content, and Antioxidant Capacity of Carrot Root','year':2025,'admitted_rows':30,'status':'VERIFIED_PARTIAL','basis':'µg/g dry weight','reason':'Tables 3–4 give raw/cooked direct individual values, explicit protocols and independent processing replication.'}]).to_csv(R/'literature_candidate_registry.csv',index=False)
pd.DataFrame([{'category':'EXCLUDED_TABLE_VALUES','doi':'10.3390/app15010254','reason':'m-Coumaric acid and vanillic acid lack exact established descriptor identities in the current master. Rutin is zero after every treatment and cannot form a ratio; quercetin and quercetin-3-O-glucoside are absent in raw. Other carotenoid isomers/entities outside existing exact identities and all aggregate assays are excluded.'}]).to_csv(R/'excluded_candidates.csv',index=False)
prior=pd.read_csv(R.parent/'batch_011'/'source_verification_ledger.csv');extra=pd.DataFrame([{'doi':'10.3390/app15010254','paper_title':'Effect of Heat Treatment Methods on Color, Bioactive Compound Content, and Antioxidant Capacity of Carrot Root','source_url':'https://bazawiedzy.uwm.edu.pl/seam/resource/rest/download/UWM5c81e3a9437b478c8b5e0f733dbebe96?entityId=UWMff3e5c19c3f848a096a3ce1f7d8d0cd7&entityType=article','locator':'Tables 3–4; Methods §§2.2–2.5.2','rows_admitted':30,'compound':'Caffeic, chlorogenic, ferulic and p-coumaric acids; lutein; beta-carotene','basis':'µg/g dry weight','analytical_method':'Individual UHPLC-DAD-MS phenolics; RP-HPLC-DAD carotenoids','admission_status':'VERIFIED_PARTIAL','rationale':'Direct raw/cooked means ± SD with exact defined whole-carrot cooking protocols and three independent process repetitions.'}]);pd.concat([prior,extra],ignore_index=True,sort=False).to_csv(R/'source_verification_ledger.csv',index=False)
master.groupby('doi').agg(observations=('observation_id','size'),compounds=('compound','nunique'),foods=('food_matrix','nunique'),methods=('cooking_method_normalized','nunique'),bases=('measurement_basis',lambda x:'; '.join(sorted(x.dropna().unique())))).reset_index().to_csv(R/'source_coverage_analysis.csv',index=False)
write('dataset_expansion_report.md',f'''# Scientific dataset expansion — controlled batch 012

The controlled master becomes **{len(master)} verified observations from {master.doi.nunique()} DOI families**. Batch 012 adds 30 primary-table pairs from Narwojsz et al. (2025), DOI `10.3390/app15010254`, and preserves all 719 parent rows.

Tables 3–4 directly report individual UHPLC-DAD-MS phenolics and RP-HPLC-DAD carotenoids in whole unpeeled carrot roots. The six compatible established identities span boiling, steel-pot steaming, combi-oven steaming, baking and sous-vide. All values remain µg/g dry weight. No zeros, technical replicates or aggregate endpoints are used, and absent exact identities are not inferred. No model is retrained; 251 observations remain to the 1,000 target.
''')
write('reproduction_instructions.md','''# Reproduction
Run `python build_batch_012.py`, then `python validate_batch_012.py`. It reads only Batch 011 and writes only this package; no historical package, Git, or Stage B/C/D file is changed.
''')
m={'package':'StageA_DatasetExpansion1000_Batch012_2026-11-10','parent_rows':719,'parent_sha256':sha(PARENT),'new_rows':30,'total_rows':len(master),'new_doi_families':1,'strict_cross_source_replications_created':0,'target_1000_reached':False,'stage_c_integration_authorized':False};(R/'manifest.json').write_text(json.dumps(m,indent=2)+'\n',encoding='utf-8');(R/'SHA256SUMS.txt').write_text('\n'.join(f'{sha(p)}  {p.name}' for p in sorted(R.iterdir()) if p.is_file() and p.name!='SHA256SUMS.txt')+'\n',encoding='utf-8');print(json.dumps(m,indent=2))
